const spokenNumbers={'khong':0,'mot':1,'hai':2,'ba':3,'bon':4,'tu':4,'nam':5,'sau':6,'bay':7,'tam':8,'chin':9,'muoi':10,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'half':.5,'nua':.5};
function spokenDigits(text){let n=normalizeText(text).replace(/\bmuoi (mot|hai|ba|bon|tu|nam|sau|bay|tam|chin)\b/g,(_,x)=>String(10+spokenNumbers[x])).replace(/\b(hai|ba|bon|nam) muoi\b/g,(_,x)=>String(spokenNumbers[x]*10));return n.replace(/\b(khong|mot|hai|ba|bon|tu|nam|sau|bay|tam|chin|muoi|one|two|three|four|five|six|seven|eight|nine|ten|half|nua)\b(?=\s+(?:kg|ky|ki|kilo|kilogram|g|gram|lit|l|ml|qua|cai|bo|hop|chai|goi|mieng|tui|khay|con|trung|eggs|pieces|bunches|bottle|bottles|packs|nguoi|people|servings)\b)/g,x=>String(spokenNumbers[x]))}
